  const disabled = false;
  const expanded = false;
  const loading = false;
  const iconAlign = 'left';

  const size = ['tiny', 'regular', 'large'];

  const icon = 'refresh';
  const children = 'Button';
  return (
    <div className="d-flex w-25">
      {size.map((IconSize, ind) => {
        return (
          <div key={ind} className="mr-5">
            <div className="h-50">
              <Button
                onClick={action('button-clicked')}
                onMouseEnter={action('mouse-enter')}
                onMouseLeave={action('mouse-leave')}
                appearance={'basic'}
                size={IconSize}
                expanded={expanded}
                disabled={disabled}
                loading={loading}
                icon={icon}
                iconAlign={iconAlign}
                aria-label="Refresh"
              >
                {children}
              </Button>
            </div>
            <br />
            <Text weight="strong">{IconSize.charAt(0).toUpperCase() + IconSize.slice(1)}</Text>
          </div>
        );
      })}
    </div>
  );
}"},"__isArgsStory":false,"__id":"components-button-variants-icon-icon-left--icon-left","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"type":{"name":"type","description":"Type of `Button`","type":{"required":false,"name":"enum","value":["undefined","button","submit","reset"]},"table":{"type":{"summary":"undefined | "button" | "submit" | "reset""},"defaultValue":null}},"size":{"name":"size","description":"The size of `Button`","type":{"required":false,"name":"enum","value":["undefined","regular","tiny","large"]},"table":{"type":{"summary":"undefined | "regular" | "tiny" | "large""},"defaultValue":{"summary":""regular""}}},"appearance":{"name":"appearance","description":"Color of the `Button`

