  const disabled = false;
  const expanded = false;
  const loading = false;
  const children = 'Delete';
  const style = {
    justifyContent: 'space-between',
  };

  return (
    <div className="d-flex w-25" style={style}>
      <div className="mr-9">
        <Button
          onClick={action('button-clicked')}
          onMouseEnter={action('mouse-enter')}
          onMouseLeave={action('mouse-leave')}
          appearance={'alert'}
          size={'regular'}
          expanded={expanded}
          disabled={disabled}
          loading={loading}
          aria-label="Delete"
        >
          {children}
        </Button>
        <br />
        <Text weight="strong">Default</Text>
      </div>
      <div className="mr-9">
        <Button
          onClick={action('button-clicked')}
          onMouseEnter={action('mouse-enter')}
          onMouseLeave={action('mouse-leave')}
          appearance={'alert'}
          size={'regular'}
          expanded={expanded}
          disabled={true}
          loading={loading}
          aria-label="Delete"
        >
          {children}
        </Button>
        <br />
        <Text weight="strong">Disabled</Text>
      </div>
      <div className="mr-9">
        <Button
          onClick={action('button-clicked')}
          onMouseEnter={action('mouse-enter')}
          onMouseLeave={action('mouse-leave')}
          appearance={'alert'}
          size={'regular'}
          expanded={expanded}
          disabled={disabled}
          loading={true}
          aria-label="Loading"
        >
          {''}
        </Button>
        <br />
        <Text weight="strong">Loading</Text>
      </div>
    </div>
  );
}"},"__isArgsStory":false,"__id":"components-button-variants-state-alert--alert","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"type":{"name":"type","description":"Type of `Button`","type":{"required":false,"name":"enum","value":["undefined","button","submit","reset"]},"table":{"type":{"summary":"undefined | "button" | "submit" | "reset""},"defaultValue":null}},"size":{"name":"size","description":"The size of `Button`","type":{"required":false,"name":"enum","value":["undefined","regular","tiny","large"]},"table":{"type":{"summary":"undefined | "regular" | "tiny" | "large""},"defaultValue":{"summary":""regular""}}},"appearance":{"name":"appearance","description":"Color of the `Button`

