  const monthsInView = 1;

  const dateValue = new Date('Jan 11 2021');

  const startDate = new Date('Jan 15 2021');

  const endDate = new Date('Jan 20 2021');

  const view = 'year';

  const rangePicker = false;

  const rangeLimit = 0;

  const firstDayOfWeek = 'saturday';

  const disabledBefore = new Date('Jan 20 2015');

  const disabledAfter = new Date('Jan 20 2028');

  const jumpView = true;

  const yearNav = -1;

  const monthNav = -1;

  const attr = {};
  if (disabledBefore) attr.disabledBefore = disabledBefore;
  if (disabledAfter) attr.disabledAfter = disabledAfter;
  if (rangeLimit) attr.rangeLimit = rangeLimit;
  if (yearNav !== -1) attr.yearNav = yearNav;
  if (monthNav !== -1) attr.monthNav = monthNav;

  // we redefine this function here because in storybook.json we donot get imported functions.
  const convertToDate = (
    d, format, validators
  ) => {
    let dateVal;

    if (d) {
      if (typeof d === 'number') {
        dateVal = new Date(d);
      } else if (typeof d === 'string') {
        return format ? translateToDate(format, d, validators) : undefined;
      } else if (!(d instanceof Date)) {
        const { year, month, date } = d;
        dateVal = new Date(year, month, date, 0, 0, 0);
      } else {
        dateVal = d;
      }
    }
    return dateVal;
  };

  return (
    <Card className="d-inline-flex" shadow="light">
      <Calendar
        monthsInView={monthsInView}
        rangePicker={rangePicker}
        jumpView={jumpView}
        date={convertToDate(dateValue)}
        startDate={convertToDate(startDate)}
        endDate={convertToDate(endDate)}
        onDateChange={(currDate) => action(`on date change : ${currDate}`)()}
        onRangeChange={(sDate, eDate) => action(`on range change: ${sDate} - ${eDate}`)()}
        view={view}
        firstDayOfWeek={firstDayOfWeek}
        {...attr}
      />
    </Card>
  );
}"},"__isArgsStory":false,"__id":"components-calendar-all--all","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"onDateChange":{"name":"onDateChange","description":"Callback function called when date is changed","type":{"required":false,"name":"function","value":"((date: Date) => void) | undefined"},"table":{"type":{"summary":"((date: Date) => void) | undefined"},"defaultValue":null}},"onRangeChange":{"name":"onRangeChange","description":"Callback function called when range is changed","type":{"required":false,"name":"function","value":"((startDate: Date | undefined, endDate: Date | undefined) => void) | undefined"},"table":{"type":{"summary":"((startDate: Date | undefined, endDate: Date | undefined) => void) | undefined"},"defaultValue":null}},"onDateHover":{"name":"onDateHover","description":"Callback function called when a date is hovered","type":{"required":false,"name":"function","value":"((dateData: hoveredDateProps, evnt: OnHover) => void) | undefined"},"table":{"type":{"summary":"((dateData: hoveredDateProps, evnt: OnHover) => void) | undefined"},"defaultValue":null}},"onMonthHover":{"name":"onMonthHover","description":"Callback function called when a month is hovered","type":{"required":false,"name":"function","value":"((monthData: hoveredMonthProps, evnt: OnHover) => void) | undefined"},"table":{"type":{"summary":"((monthData: hoveredMonthProps, evnt: OnHover) => void) | undefined"},"defaultValue":null}},"onYearHover":{"name":"onYearHover","description":"Callback function called when a year is hovered","type":{"required":false,"name":"function","value":"((yearData: hoveredYearProps, evnt: OnHover) => void) | undefined"},"table":{"type":{"summary":"((yearData: hoveredYearProps, evnt: OnHover) => void) | undefined"},"defaultValue":null}},"date":{"name":"date","description":"Selected date","type":{"required":false,"name":"other","value":"Date | undefined"},"table":{"type":{"summary":"Date | undefined"},"defaultValue":null}},"rangePick