  const size = 'tiny';

  const label = 'Checkbox';

  const [checked, setChecked] = React.useState(false);

  const [indeterminate, setIndeterminate] = React.useState(false);

  const disabled = false;

  const onChangeHandler = (event) => {
    setChecked(!checked);
    setIndeterminate(!indeterminate);
    return action(`onChange: ${event.target.checked}`)();
  };

  return (
    <Checkbox
      checked={checked}
      indeterminate={indeterminate}
      disabled={disabled}
      size={size}
      label={label}
      onChange={onChangeHandler}
    />
  );
}"},"__isArgsStory":false,"__id":"components-checkbox-all--all","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"size":{"name":"size","description":"Size of the `Checkbox`","type":{"required":false,"name":"enum","value":["undefined","regular","tiny"]},"table":{"type":{"summary":"undefined | "regular" | "tiny""},"defaultValue":{"summary":""regular""}}},"defaultChecked":{"name":"defaultChecked","description":"Default value of checked (Used in case of uncontrolled `Checkbox`)","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":null}},"checked":{"name":"checked","description":"Denotes Selection (Used in case of controlled `Checkbox`)","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":null}},"indeterminate":{"name":"indeterminate","description":"Used in case of nested `Checkbox`, overwrites checked if true","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":null}},"disabled":{"name":"disabled","description":"Disables the `Checkbox`, making it unable to be pressed","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":null}},"label":{"name":"label","description":"Describes Label of the `Checkbox`","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"string | undefined"},"defaultValue":null}},"helpText":{"name":"helpText","description":"Describes Help Text of the `Checkbox`","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"string | undefined"},"defaultValue":null}},"name":{"name":"name","description":"Name of the `Checkbox`","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"str