  const style = {
    display: 'flex',
    'flex-direction': 'column',
    paddingLeft: '25px',
  };
  const parentObj = { checked: false, indeterminate: true };
  const labels = ['Diabetes Eye Exam', 'HbA1c Test in last 12 months', 'Falls Risk Assessment'];
  const childArray = [true, true, false];

  const [checked, setChecked] = React.useState(childArray);
  const [parentStatus, setParentStatus] = React.useState(parentObj);

  const handleParentChange = (event) => {
    const updatedArray = [...childArray].fill(event.target.checked);
    setChecked(updatedArray);
    setParentStatus({ indeterminate: event.target.indeterminate, checked: event.target.checked });
  };

  const handleChildChange = (event, index) => {
    const updateCheck = [...checked];
    updateCheck[index] = event.target.checked;
    const totalCount = labels.length;
    const countT = updateCheck.filter(Boolean).length;
    const status = countT < totalCount;
    const obj = countT > 0 ? { checked: !status, indeterminate: status } : { checked: !status, indeterminate: false };
    setChecked(updateCheck);
    setParentStatus(obj);
  };

  return (
    <div>
      <Checkbox
        checked={parentStatus.checked}
        indeterminate={parentStatus.indeterminate}
        label={'Measures'}
        onChange={handleParentChange}
        value={'Measures'}
      />
      <div style={style}>
        {labels.map((label, ind) => {
          return (
            <Checkbox
              key={`checkbox-${ind}`}
              label={label}
              checked={checked[ind]}
              value={label}
              onChange={(c) => handleChildChange(c, ind)}
              defaultChecked={ind < 2}
              className="mt-4"
            />
          );
        })}
      </div>
    </div>
  );
}"},"__isArgsStory":false,"__id":"components-checkbox-nested-checkboxes--nested-checkboxes","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"size":{"name":"size","description":"Size of the `Checkbox`","type":{"required":false,"name":"enum","value":["undefined","regular","tiny"]},"table":{"type":{"summary":"undefined | "regular" | "tiny""},"defaultValue":{"summary":""regular""}}},"defaultChecked":{"name":"defaultChecked","description":"Default value of checked (Used in case of uncontrolled `Checkbox`)","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":null}},"checked":{"name":"checked","description":"Denotes Selection (Used in case of controlled `Checkbox`)","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":null}},"indeterminate":{"name":"indeterminate","description":"Used in case of nested `Checkbox`, overwrites checked if true","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":null}},"disabled":{"name":"disabled","description":"Disables the `Checkbox`, making it unable to be pressed","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":null}},"label":{"name":"label","description":"Describes Label of the `Checkbox`","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"string | undefined"},"defaultValue":null}},"helpText":{"name":"helpText","description":"Describes Help Text of the `Checkbox`","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"string | undefined"},"defaultValue":null}},"name":{"name":"name","description":"Name of the `Checkbox`","type":{"required":false,"name":"other","value":"string | undefined"},"ta