  const monthsInView = 2;

  const startDate = new Date('Jan 12 2017');

  const endDate = new Date('Jan 20 2017');

  const inputFormat = 'mm-dd-yyyy';

  const outputFormat = 'yyyy-mm-dd';

  const view = 'year';

  const firstDayOfWeek = 'monday';

  const disabledBefore = new Date('Jan 20 2015');

  const disabledAfter = new Date('Jan 20 2028');

  const jumpView = true;

  const yearNav = -1;

  const monthNav = -1;

  const attr = {};
  if (disabledBefore) attr.disabledBefore = disabledBefore;
  if (disabledAfter) attr.disabledAfter = disabledAfter;
  if (yearNav !== -1) attr.yearNav = yearNav;
  if (monthNav !== -1) attr.monthNav = monthNav;

  return (
    <div className="w-50">
      <DateRangePicker
        withInput={true}
        startDate={startDate}
        endDate={endDate}
        inputFormat={inputFormat}
        outputFormat={outputFormat}
        jumpView={jumpView}
        onRangeChange={(sDate, eDate, sValue, eValue) =>
          action(`on range change: ${sDate} - ${eDate} ---- ${sValue} - ${eValue}`)()
        }
        view={view}
        firstDayOfWeek={firstDayOfWeek}
        monthsInView={monthsInView}
        startInputOptions={{
          required: true,
        }}
        endInputOptions={{
          required: true,
        }}
        {...attr}
      />
    </div>
  );
}"},"__isArgsStory":false,"__id":"components-daterangepicker-variants-with-input--with-input","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"size":{"name":"size","description":"Size of `Calendar`","type":{"required":true,"name":"enum","value":["large","small"]},"table":{"type":{"summary":""large" | "small""},"defaultValue":{"summary":""large""}}},"monthsInView":{"name":"monthsInView","description":"Number of months rendered in view
