les":{"height":"732px","width":"412px"},"type":"mobile"},"pixel":{"name":"Pixel","styles":{"height":"960px","width":"540px"},"type":"mobile"},"pixelxl":{"name":"Pixel XL","styles":{"height":"1280px","width":"720px"},"type":"mobile"}}},"controls":{"expanded":true},"options":{},"fileName":"./core/components/atoms/dropdown/__stories__/index.story.jsx","storySource":{"source":"() => {
  const triggerSize = 'tiny';

  const align = 'left';

  const optionType = 'ICON_WITH_META';

  const error = false;

  const disabled = false;

  const menu = false;

  const withSearch = false;

  const withCheckbox = false;

  const showApplyButton = false;

  const closeOnSelect = true;

  const icon = '';

  const placeholder = 'Select';

  const selectAllLabel = 'Select All';

  const inlineLabel = '';

  const labelLimit = 2;

  const maxHeight = 200;

  const loadersCount = 10;

  const getSearchedOptions = (options, searchTerm) => {
    const result = options.filter((option) => option.label.toLowerCase().includes(searchTerm.toLowerCase()));
    return result;
  };

  const fetchOptions = (searchTerm) => {
    const searchedOptions = searchTerm ? getSearchedOptions(dropdownOptions, searchTerm) : dropdownOptions;
    return new Promise((resolve) => {
      window.setTimeout(() => {
        resolve({
          searchTerm,
          options: searchedOptions,
          count: searchedOptions.length,
        });
      }, 1000);
    });
  };

  const customLabel = (selectedLength, totalOptions) => {
    const optionsLength = totalOptions ? totalOptions : dropdownOptions.length;
    return `${selectedLength} of ${optionsLength} are selected`;
  };

  const onChangeHandler = (selectedValues) => {
    return action(`selected values length: ${selectedValues}`)();
  };

  const onClose = (selectedValues) => {
    return action(`dropdown closed with selected values: ${selectedValues}`)();
  };

  const props = {
    triggerSize,
    align,
    icon,
    error,
    placeholder,
    inlineLabel,
    disabled,
    menu,
    closeOnSelect,
    withSearch,
    withCheckbox,
    showApplyButton,
    maxHeight,
    loadersCount,
    onClose,
    fetchOptions,
    optionType,
    selectAllLabel,
    triggerOptions: { customLabel, labelLimit },
    options: dropdownOptions,
    onChange: onChangeHandler,
  };

  const key = `checkbox${withCheckbox} applyButton:${showApplyButton} search:${withSearch}`;

  return (
    <div style={{ width: '170px', marginLeft: '128px' }} key={key}>
      <Dropdown {...props} />
    </div>
  );
}"},"__isArgsStory":false,"__id":"components-dropdown-all--all","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"selected":{"name":"selected","description":"Array of selected options <br/>
