  const dropdownOptions =  [];
  for (let i = 1; i <= 100; i++) {
    dropdownOptions.push({
      label: `Option ${i}`,
      value: `Option ${i}`,
      group: i >= 1 && i <= 40 ? 'Group 1' : 'Group 2',
      icon: 'events',
      subInfo: 'subInfo',
    });
  }

  const [selected, setSelected] = React.useState([dropdownOptions[3]]);
  const [open, setOpen] = React.useState(false);

  const onChangeHandler = (selectedValues) => {
    console.log(selectedValues);
  };

  const onUpdate = (type, options, recentSelected) => {
    switch (type) {
      case 'apply-selected':
        setOpen(!open);
        setSelected(recentSelected);
        return;
      case 'cancel-selected':
        setOpen(!open);
        return action('cancel event triggered')();
      default:
        return;
    }
  };

  const onPopperToggle = (isPopperOpen) => {
    setOpen(isPopperOpen);
  };

  return (
    <div className="w-25">
      <Text weight="strong">{'Options <= 50'}</Text><br /><br />
      <Dropdown
        options={dropdownOptions.slice(0, 50)}
        onPopperToggle={onPopperToggle}
        onUpdate={onUpdate}
        selected={selected}
        onChange={onChangeHandler}
        withCheckbox={true}
        showApplyButton={true}
        open={open}
      />
    </div>
  );
}","title":"Controlled Dropdown","props":{"components":{},"exclude":["showHead"]}}},"framework":"react","backgrounds":{"grid":{"cellSize":20,"opacity":0.5,"cellAmount":5},"values":[{"name":"light","value":"#F8F8F8"},{"name":"dark","value":"#333333"}]},"viewMode":"docs","actions":{"argTypesRegex":"^on[A-Z].*"},"a11y":{"element":"#root","manual":false},"viewport":{"viewports":{"iphone5":{"name":"iPhone 5","styles":{"height":"568px","width":"320px"},"type":"mobile"},"iphone6":{"name":"iPhone 6","styles":{"height":"667px","width":"375px"},"type":"mobile"},"iphone6p":{"name":"iPhone 6 Plus","styles":{"height":"736px","width":"414px"},"type":"mobile"},"iphone8p":{"name":"iPhone 8 Plus","styles":{"height":"736px","width":"414px"},"type":"mobile"},"iphonex":{"name":"iPhone X","styles":{"height":"812px","width":"375px"},"type":"mobile"},"iphonexr":{"name":"iPhone XR","styles":{"height":"896px","width":"414px"},"type":"mobile"},"iphonexsmax":{"name":"iPhone XS Max","styles":{"height":"896px","width":"414px"},"type":"mobile"},"iphonese2":{"name":"iPhone SE (2nd generation)","styles":{"height":"667px","width":"375px"},"type":"mobile"},"iphone12mini":{"name":"iPhone 12 mini","styles":{"height":"812px","width":"375px"},"type":"mobile"},"iphone12":{"name":"iPhone 12","styles":{"height":"844px","width":"390px"},"type":"mobile"},"iphone12promax":{"name":"iPhone 12 Pro Max","styles":{"height":"926px","width":"428px"},"type":"mobile"},"ipad":{"name":"iPad","styles":{"height":"1024px","width":"768px"},"type":"tablet"},"ipad10p":{"name":"iPad Pro 10.5-in","styles":{"height":"1112px","width":"834px"},"type":"tablet"},"ipad12p":{"name":"iPad Pro 12.9-in","styles":{"height":"1366px","width":"1024px"},"type":"tablet"},"galaxys5":{"name":"Galaxy S5","styles":{"height":"640px","width":"360px"},"type":"mobile"},"galaxys9":{"name":"Galaxy S9","styles":{"height":"740px","width":"360px"},"type":"mobile"},"nexus5x":{"name":"Nexus 5X","styles":{"height":"660px","width":"412px"},"type":"mobile"},"ne