{"args":{},"componentId":"components-dropdown-variants-static-limit","title":"Components/Dropdown/Variants/Static Limit","kind":"Components/Dropdown/Variants/Static Limit","id":"components-dropdown-variants-static-limit--static-limit","name":"Static Limit","story":"Static Limit","parameters":{"docs":{"inlineStories":true,"iframeHeight":100,"theme":{"base":"light","colorPrimary":"#0000001a","colorSecondary":"deepskyblue","appBg":"white","appContentBg":"white","appBorderColor":"#0000001a","appBorderRadius":4,"fontBase":""Nunito Sans", "Open Sans", sans-serif","fontCode":"monospace","textColor":"black","textInverseColor":"rgba(255,255,255,0.9)","textMutedColor":"#666666","barTextColor":"silver","barSelectedColor":"black","barBg":"white","inputBg":"white","inputBorder":"silver","inputTextColor":"black","inputBorderRadius":4,"brandTitle":"Masala Design System v2.10.0-0","brandUrl":"https://github.com/innovaccer/design-system/"},"docPage":{"customCode":"() => {
  const staticLimit = 50;
  const dropdownOptions = [];
  for (let i = 1; i <= 100; i++) {
    dropdownOptions.push({
      label: `Option ${i}`,
      value: `Option ${i}`,
      group: i <= 40 ? 'Group 1' : 'Group 2'
    });
  }
  const BooleanValue = [true, false];

  const getSearchedOptions = (options, searchTerm) => {
    const result = options.filter((option) => option.label.toLowerCase().includes(searchTerm.toLowerCase()));
    return result;
  };

  const fetchOptions = (searchTerm) => {
    const searchedOptions = searchTerm ? getSearchedOptions(dropdownOptions, searchTerm) : dropdownOptions;
    return new Promise(resolve => {
      window.setTimeout(() => {
        resolve({
          searchTerm,
          options: searchedOptions,
          count: searchedOptions.length,
        });
      }, 1000);
    });
  };
  return (
    <div className='d-flex'>
      <div className='mr-10 w-25'>
        <Text weight="strong">{`Options > ${staticLimit}`}</Text> <br /><br />
        <Dropdown
          withCheckbox={true}
          staticLimit={staticLimit}
          fetchOptions={fetchOptions}
        />
      </div>
      <div className='mr-10 w-25'>
        <Text weight="strong">{`Options <= ${staticLimit}`}</Text> <br /><br />
        <Dropdown
          withCheckbox={true}
          staticLimit={staticLimit}
          options={dropdownOptions.slice(0, staticLimit)}
        />
      </div>
    </div>
  )
}","props":{"components":{},"exclude":["showHead"]}}},"framework":"react","backgrounds":{"grid":{"cellSize":20,"opacity":0.5,"cellAmount":5},"values":[{"name":"light","value":"#F8F8F8"},{"name":"dark","value":"#333333"}]},"viewMode":"docs","actions":{"argTypesRegex":"^on[A-Z].*"},"a11y":{"element":"#root","manual":false},"viewport":{"viewports":{"iphone5":{"name":"iPhone 5","styles":{"height":"568px","width":"320px"},"type":"mobile"},"iphone6":{"name":"iPhone 6","styles":{"height":"667px","width":"375px"},"type":"mobile"},"iphone6p":{"name":"iPhone 6 Plus","styles":{"height":"736px","width":"414px"},"type":"mobile"},"iphone8p":{"name":"iPhone 8 Plus","styles":{"height":"736px","width":"414px"},"type":"mobile"},"iphonex":{"name":"iPhone X","styles":{"height":"812px","width":"375px"},"type":"mobile"},"iphonexr":{"name":"iPhone XR","styles":{"height":"896px","width":"414px"},"type":"mobile"},"iphonexsmax":{"name":"iPhone XS Max","styles":{"height":"896px","width":"414px"},"type":"mobile"},"iphonese2":{"name":"iPhone SE (2nd generation)","styles":{"height":"667px","width":"375px"},"type":"mobile"},"iphone12mini":{"name":"iPhone 12 mini","styles":{"height":"812px","width":"375px"},"type":"mobile"},"iphone12":{"name":"iPhone 12","styles":{"height":"844px","width":"390px"},"type":"mobile"},"iphone12promax":{"name":"iPhone 12 Pro Max","styles":{"height":"926px","width":"428px"},"type":"mobile"},"ipad":{"name":"iPad","styles":{"height":"1024px","width":"768px"},"type":"tablet"},"ipad10p":{"name":"iPad Pro 10.5-in","styles":{"height":"1112px","width":"834px"},"type":"tablet"},"ipad12p":{"name":"iPad Pro 12.9-in","styles":{"height":"1366px","width":"1024px"},"type":"tablet"},"galaxys5":{"name":"Galaxy S5","styles":{"height":"640px","width":"360px"},"type":"mobile"},"galaxys9":{"name":"Galaxy S9","styles":{"height":"740px","width":"360px"},"type":"mobile"},"nexus5x":{"name":"Nexus 5X","styles":{"height":"660px","width":"412px"},"type":"mobile"},"nexus6p":{"name":"Nexus 6P","sty