{"args":{},"componentId":"components-dropzone-all","title":"Components/Dropzone/All","kind":"Components/Dropzone/All","id":"components-dropzone-all--all","name":"All","story":"All","parameters":{"docs":{"inlineStories":true,"iframeHeight":100,"theme":{"base":"light","colorPrimary":"#0000001a","colorSecondary":"deepskyblue","appBg":"white","appContentBg":"white","appBorderColor":"#0000001a","appBorderRadius":4,"fontBase":""Nunito Sans", "Open Sans", sans-serif","fontCode":"monospace","textColor":"black","textInverseColor":"rgba(255,255,255,0.9)","textMutedColor":"#666666","barTextColor":"silver","barSelectedColor":"black","barBg":"white","inputBg":"white","inputBorder":"silver","inputTextColor":"black","inputBorderRadius":4,"brandTitle":"Masala Design System v2.10.0-0","brandUrl":"https://github.com/innovaccer/design-system/"},"docPage":{"customCode":"() => {
  const [files, setFiles] = React.useState([]);

  const getSize = (size) => (
    `${(size / (1024 * 1024)).toFixed(2)} MB`
  );

  const onDelete = (fileItem) => {
    const updatedFiles = files.filter((file) => file.id !== fileItem.id);
    setFiles(updatedFiles);
  };

  const onDropHandler = (event, acceptedFiles, rejectedFiles) => {
    const acceptedFileDetailList = acceptedFiles.map((file, id) => (
      {
        file,
        id: files.length + id,
        fileSize: getSize(file.size),
        networkError: false,
      }
    ));

    const rejectedFilesDetailList = rejectedFiles.map((rejectedFile, id) => {
      const { file, errors } = rejectedFile;
      const errorMessageArray = errors.map((error) => error.message);
      return {
        file,
        id: files.length + id,
        fileSize: getSize(file.size),
        status: 'error',
        errorMessage: errorMessageArray.join(' and '),
        networkError: false,
      };
    });
    const updatedFiles = [...files, ...acceptedFileDetailList, ...rejectedFilesDetailList];
    setFiles(updatedFiles);
  };

  const actionRenderer = (fileItem) => {
    return (
      <React.Fragment>
        {fileItem.networkError && (
          <Button
            aria-label={`Remove ${fileItem.file.name}`}
            appearance="transparent"
            icon="refresh"
            size="regular"
            onClick={() => onDelete(fileItem.id)}
            className={'cursor-pointer'}
          />
        )}
        <Button
          aria-label={`Remove ${fileItem.file.name}`}
          appearance="transparent"
          icon="close"
          size="regular"
          onClick={() => onDelete(fileItem)}
          className={'cursor-pointer'}
        />
      </React.Fragment>
    );
  }

  return (
    <React.Fragment>
      <Dropzone
        accept="image/jpeg, image/png"
        formatLabel="Accepted formats: PDF, jpg"
        sizeLabel="Maximum size: 25 MB"
        multiple={true}
        onDrop={onDropHandler}
        className="mb-5"
        sampleFileLink={(
          <Link
            href="http://www.adobe.com/content/dam/Adobe/en/accessibility/pdfs/accessing-pdf-sr.pdf"
            download="Test.pdf"
            target="_blank"
          >
            Download sample file
          </Link>
        )}
      />
      <FileList
        fileList={files}
        actionRenderer={actionRenderer}
      />
    </React.Fragment>
  );
