  const [files, setFiles] = React.useState([]);
  const getSize = (size) => `${(size / (1024 * 1024)).toFixed(2)} MB`;

  const onDelete = (id) => {
    const updatedFiles = files.filter((file) => file.id !== id);
    setFiles(updatedFiles);
  };

  const onDropHandler = (_event, acceptedFiles, rejectedFiles) => {
    const acceptedFileDetailList = acceptedFiles.map((file, id) => ({
      file,
      id: files.length + id,
      fileSize: getSize(file.size),
      networkError: false,
      status: 'completed',
    }));

    const rejectedFilesDetailList = rejectedFiles.map((rejectedFile, id) => {
      const { file, errors } = rejectedFile;
      const errorMessageArray = errors.map((error) => error.message);
      return {
        file,
        id: files.length + id,
        fileSize: getSize(file.size),
        status: 'error',
        errorMessage: errorMessageArray.join(' and '),
        networkError: false,
      };
    });

    const updatedFiles = [...files, ...acceptedFileDetailList, ...rejectedFilesDetailList];
    setFiles(updatedFiles);
  };

  const actionRenderer = (fileItem) => {
    return (
      <React.Fragment>
        {fileItem.networkError && (
          <Button
            aria-label={`Remove ${fileItem.file.name}`}
            appearance="transparent"
            icon="refresh"
            size="regular"
            onClick={() => onDelete(fileItem.id)}
            className={'cursor-pointer'}
          />
        )}
        <Button
          aria-label={`Remove ${fileItem.file.name}`}
          appearance="transparent"
          icon="close"
          size="regular"
          onClick={() => onDelete(fileItem.id)}
          className={'cursor-pointer'}
        />
      </React.Fragment>
    );
  };

  return (
    <React.Fragment>
      <Dropzone
        accept="image/jpeg, image/png"
        formatLabel="Accepted formats: PDF, jpg"
        sizeLabel="Maximum size: 25 MB"
        multiple={true}
        onDrop={onDropHandler}
        className="mb-5"
        sampleFileLink={
          <Link
            href="http://www.adobe.com/content/dam/Adobe/en/accessibility/pdfs/accessing-pdf-sr.pdf"
            download="Test.pdf"
            target="_blank"
          >
            Download sample file
          </Link>
        }
      />
      <FileList fileList={files.map(({ file, metadata }) => ({ file, ...metadata }))} actionRenderer={actionRenderer} />
    </React.Fragment>
  );
}"},"__isArgsStory":false,"__id":"components-dropzone-all--all","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"formatLabel":{"name":"formatLabel","description":"Description of accepted formats in `FileUploader`","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"string | undefined"},"defaultValue":null}},"type":{"name":"type","description":"Size of `Dropzone`","type":{"required":false,"name":"enum","value":["standard","compressed","tight"]},"table":{"type":{"summary":""standard" | "compressed" | "tight""},"defaultValue":{"summary":""standard""}}},"sizeLabel":{"name":"sizeLabel","description":"Description of maximum size in `FileUploader`","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"string | undefined"},"defaultValue":null}},"sampleFileLink":{"name":"sampleFileLink","description":"Link component to download sample file","type":{"required":false,"name":"other","value":"ReactNode"},"table":{"type":{"summary":"ReactNode"},"defaultValue":null}},"className":{"name":"className","description":"Adds custom class","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"string | undefined"},"defaultValue":null}},"data-test":{"name":"data-test","description":"Stores custom testing data private to the component.","type":{"required":false,"name":"other","value":"string | undefined"},"table":{"type":{"summary":"string | undefined"},"defaultValue":null}},"accept":{"name":"accept","description":"Set accepted file types.","type":{"required":false,"name":"other","value":"string | string[] | undefined"},"table":{"type":{"summary":"string | string[] | undefined"},"defaultValue":null}},"multiple":{"name":"multiple","description":"Allow drag 'n' drop (or selection from the file dialog) of multiple files","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"