        <Paragraph>
          Card Sections include supporting text like an article summary or a restaurant description.
        </Paragraph>
      </FullscreenModal>
    </div>
  );
}"},"__isArgsStory":false,"__id":"components-fullscreenmodal-customized--customized","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"dimension":{"name":"dimension","description":"Dimension of `Fullscreen Modal`","type":{"required":false,"name":"enum","value":["large","medium"]},"table":{"type":{"summary":""large" | "medium""},"defaultValue":{"summary":""medium""}}},"open":{"name":"open","description":"Handles open/close state","type":{"required":true,"name":"boolean"},"table":{"type":{"summary":"boolean"},"defaultValue":null}},"onClose":{"name":"onClose","description":"onClose callback to be called on `Fullscreen Modal` close","type":{"required":false,"name":"function","value":"((event?: Event | MouseEvent<HTMLElement, MouseEvent> | undefined, reason?: string | undefined) => void) | undefined"},"table":{"type":{"summary":"((event?: Event | MouseEvent<HTMLElement, MouseEvent> | undefined, reason?: string | undefined) => void) | undefined"},"defaultValue":null}},"headerOptions":{"name":"headerOptions","description":"Header options (doesn't work if `header` prop is used)

