  const [open, setOpen] = React.useState(false);
  const position = 'bottom';
  const on = 'hover';
  const appendToBody = true;
  const hoverable = true;
  const closeOnBackdropClick = true;
  const closeOnScroll = true;
  const hideOnReferenceEscape = true;
  const dark = false;

  const onToggle = () => {
    setOpen(!open);
  };

  const trigger = <Button appearance="basic">Open Popup</Button>;

  const options = {
    trigger,
    position,
    appendToBody,
    dark,
    closeOnBackdropClick,
    closeOnScroll,
    hideOnReferenceEscape,
    on,
    hoverable,
    open,
    onToggle,
  };
  if (on === 'hover') delete options.onToggle;

  const ref = React.useRef<HTMLDivElement>(null);

  return (
    <div ref={ref} style={{ height: 150, border: '1px dashed', padding: 20, overflow: 'auto' }}>
      <Popover {...options} boundaryElement={ref}>
        <div style={{ width: 100 }} className="mx-6 my-6">
          <Text>Popup</Text>
          <Button className="mt-4" appearance="primary" onClick={action('button clicked inside popover')}>
            Click
          </Button>
        </div>
      </Popover>
      <div style={{ height: 300 }} />
    </div>
  );
}"},"__isArgsStory":false,"__id":"components-popover-variants-boundary-element--boundary-element","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"children":{"name":"children","description":"To be rendered in `Popover` component","type":{"required":true,"name":"other","value":"ReactNode"},"table":{"type":{"summary":"ReactNode"},"defaultValue":null}},"position":{"name":"position","description":"Position to place the `trigger`","type":{"required":true,"name":"enum","value":["bottom","top","top-start","top-end","bottom-start","bottom-end","left","right"]},"table":{"type":{"summary":""bottom" | "top" | "top-start" | "top-end" | "bottom-start" | "bottom-end" | "left" | "right""},"jsDocTags":{"params":[{"name":"Position","description":"'top' | 'top-start' | 'top-end' | 'bottom'
