  const [open, setOpen] = React.useState(true);
  const [page, setPage] = React.useState(2);
  const [animate, setAnimate] = React.useState(true);

  const onClose = () => {
    setOpen(!open);
  };

  React.useEffect(() => {
    setAnimate(true);
    return () => {
      setAnimate(false);
    }
  }, [page])

  const backIconCallback = (e) => {
    console.log('back icon clicked');
    setPage(1);
  };

  const headerOptions = {
    backIconCallback,
    backIcon: page === 2,
    heading: `Heading ${page}`,
    subHeading: 'Subheading',
  };

  const options = {
    onClose,
    open,
    headerOptions,
    stickFooter: true,
    backdropClose: true,
    footer: (
      <>
        {page === 1 && (
          <Button
            appearance="primary"
            className="mr-4"
            onClick={() => setPage(2)}
          >
            Next
          </Button>
        )}
        {page === 2 && (
          <>
