{"args":{},"componentId":"components-stepper-variants-stepper-with-skip","title":"Components/Stepper/Variants/Stepper With Skip","kind":"Components/Stepper/Variants/Stepper With Skip","id":"components-stepper-variants-stepper-with-skip--stepper-with-skip","name":"Stepper With Skip","story":"Stepper With Skip","parameters":{"docs":{"inlineStories":true,"iframeHeight":100,"theme":{"base":"light","colorPrimary":"#0000001a","colorSecondary":"deepskyblue","appBg":"white","appContentBg":"white","appBorderColor":"#0000001a","appBorderRadius":4,"fontBase":""Nunito Sans", "Open Sans", sans-serif","fontCode":"monospace","textColor":"black","textInverseColor":"rgba(255,255,255,0.9)","textMutedColor":"#666666","barTextColor":"silver","barSelectedColor":"black","barBg":"white","inputBg":"white","inputBorder":"silver","inputTextColor":"black","inputBorderRadius":4,"brandTitle":"Masala Design System v2.10.0-0","brandUrl":"https://github.com/innovaccer/design-system/"},"docPage":{"customCode":"() => {
  const steps = [
    {
      label: 'Step',
      value: 'Step1'
    },
    {
      label: 'Step',
      value: 'Step2'
    },
    {
      label: 'Step',
      value: 'Step3'
    },
    {
      label: 'Step',
      value: 'Step4'
    }
  ];

  const [active, setActive] = React.useState(0);
  const [completed, setCompleted] = React.useState(active - 1);
  const [skipIndexes, setSkipIndexes] = React.useState([]);
  const requiredSteps = [0];

  const onChange = (activeStep) => {
    setActive(activeStep);
  };

  const onClickHandler = () => {
    if (skipIndexes.includes(active)) {
      const updatedSkip = [...skipIndexes];
      const index = updatedSkip.findIndex(skippedIndex => skippedIndex === active);
      updatedSkip.splice(index, 1);
      setSkipIndexes(updatedSkip);
    }
    const updatedActive = active > completed ? active + 1 : completed + 1;
    if (active > completed) setCompleted(active);
    setActive(updatedActive);
  };

  const onSkipHandler = () => {
    const updatedActive = active > completed ? active + 1 : completed + 1;
    setActive(updatedActive);
    if (!skipIndexes.includes(active)) {
      setSkipIndexes([...skipIndexes, active]);
    }
  };

  return (
    <div
      className="d-flex flex-column justify-content-between align-items-end py-4 px-4 bg-secondary-lightest"
      style={{ height: '200px' }}
    >
      <div className="d-flex justify-content-center py-5 bg-light w-100">
        <Stepper
          steps={steps}
          active={active}
          completed={completed}
          onChange={onChange}
          skipIndexes={skipIndexes}
        />
      </div>
      <br />
      <div className="w-25 d-flex justify-content-end">
        <Button onClick={onSkipHandler} disabled={requiredSteps.includes(active)} className="mr-4">Skip</Button>
        <Button onClick={onClickHandler} appearance="primary">Next</Button>
      </div>
    </div>
  );
