        "name": "Well-child Visit",
        "status": "Draft",
        "lastUpdated": "April 19, 2020",
        "recipients": 11890
    }
];

  const statusAppearance = {
    'In Progress': 'info',
    'Scheduled': 'warning',
    'Draft': 'default',
    'Failed': 'alert'
  };

  const schema = [
    {
      name: 'name',
      displayName: 'Name',
      width: '30%',
      cellType: 'WITH_META_LIST',
      sorting: false,
      translate: a => ({
        title: a.name,
        metaList: [`${a.recipients} recipients`]
      }),
    },
    {
      name: 'status',
      displayName: 'Status',
      width: '20%',
      cellType: 'STATUS_HINT',
      sorting: false,
      filters: [
        { label: 'In Progress', value: 'In Progress' },
        { label: 'Scheduled', value: 'Scheduled' },
        { label: 'Draft', value: 'Draft' },
        { label: 'Failed', value: 'Failed' }
      ],
      onFilterChange: (a, filters) => {
        for (const filter of filters) {
          if (a.status === filter) return true;
        }
        return false;
      },
      translate: a => {
        const status = a.status;
        return ({
          title: status,
          statusAppearance: statusAppearance[status]
        });
      }
    },
    {
      name: 'lastUpdated',
      displayName: 'Last Updated on',
      width: '30%',
      sorting: false,
    },
    {
      name: 'user',
      displayName: '',
      sorting: false,
      width: '20%',
      cellRenderer: (props) => {
        const { data } = props;
        return (
          <div className="d-flex align-items-center justify-content-end flex-grow-1">
            <Avatar firstName={data.firstName} lastName={data.lastName} />
            <div style={{ width: 'var(--spacing-3)' }} className="ml-6">
              <Dropdown
                triggerOptions={{
                  customTrigger: () => (
                    <Button icon="more_horiz" appearance="transparent" />
                  )
                }}
                menu={true}
                align="left"
                options={[
                  { label: 'Edit', value: 'Edit' },
                  { label: 'Delete', value: 'Delete' }
                ]}
                popoverOptions={{appendToBody:false}}
              />
            </div>
          </div>
        );
      }
    }
  ];

  return (
    <Card>
      <Table
        showMenu={false}
        type="resource"
        data={data}
        schema={schema}
        withHeader={true}
        filterPosition="HEADER"
        onSelect={(rowIndex, selected, selectedList, selectAll) =>
          console.log(`on-select:- rowIndex: ${rowIndex} selected: ${selected} selectedList: ${JSON.stringify(selectedList)} selectAll: ${selectAll}`)
        }
        headerOptions={{
          withSearch: true
        }}
        filterList={{
          status: ['In Progress', 'Scheduled', 'Draft', 'Failed']
        }}
        onSearch={(currData, searchTerm) => {
          return currData.filter(d =>
            d.firstName.toLowerCase().match(searchTerm.toLowerCase())
            || d.lastName.toLowerCase().match(searchTerm.toLowerCase())
            || d.name.toLowerCase().match(searchTerm.toLowerCase())
          );
        }}
        withPagination={true}
        paginationType="basic"
        pageSize={4}
        onPageChange={newPage => console.log(`on-page-change:- ${newPage}`)}
      />
    </Card>
  );
};
