es":{"height":"732px","width":"412px"},"type":"mobile"},"pixel":{"name":"Pixel","styles":{"height":"960px","width":"540px"},"type":"mobile"},"pixelxl":{"name":"Pixel XL","styles":{"height":"1280px","width":"720px"},"type":"mobile"}}},"controls":{"expanded":true},"options":{},"fileName":"./core/components/organisms/table/__stories__/Selection.story.jsx","storySource":{"source":"() => {
  const schema = [
    {
      name: 'name',
      displayName: 'Name',
      width: '30%',
      separator: true,
      translate: (a) => ({
        title: `${a.lastName}, ${a.firstName}`,
        firstName: a.firstName,
        lastName: a.lastName,
      }),
      cellType: 'AVATAR_WITH_TEXT',
      sorting: false,
    },
    {
      name: 'role',
      displayName: 'Role',
      width: 250,
      sorting: false,
    },
    {
      name: 'manager',
      displayName: 'Manager',
      width: 180,
      sorting: false,
    },
    {
      name: 'last_login',
      displayName: 'Last Login',
      width: 100,
      sorting: false,
    },
    {
      name: 'status',
      displayName: 'Status',
      width: 200,
      cellType: 'STATUS_HINT',
      sorting: false,
      translate: (a) => ({
        title: a.status,
        statusAppearance: a.status === 'Inactive' ? 'default' : 'success',
      }),
    },
  ];
  return (
    <Card>
      <Table
        loaderSchema={loaderSchema}
        type="resource"
        data={data}
        schema={schema}
        showMenu={false}
        withHeader={true}
        withCheckbox={true}
        onSelect={(rowIndex, selected, selectedList, selectAll) =>
          action(
            `on-select:- rowIndex: ${rowIndex} selected: ${selected} selectedList: ${JSON.stringify(
              selectedList
            )} selectAll: ${selectAll}`
          )()
        }
        headerOptions={{
          withSearch: true,
        }}
        onSearch={(currData, searchTerm) => {
          return currData.filter(
            (d) =>
              d.firstName.toLowerCase().match(searchTerm.toLowerCase()) ||
              d.lastName.toLowerCase().match(searchTerm.toLowerCase())
          );
        }}
        withPagination={true}
        pageSize={5}
        onPageChange={(newPage) => action(`on-page-change:- ${newPage}`)()}
      />
    </Card>
  );
}"},"__isArgsStory":false,"__id":"components-table-selection--selection","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"showHead":{"name":"showHead","description":"Controls Table Head display","type":{"required":false,"name":"other","value":"boolean | undefined"},"table":{"type":{"summary":"boolean | undefined"},"defaultValue":{"summary":"true"}}},"type":{"name":"type","description":"Type of Table

