  const appearances = ['info', 'success', 'alert', 'warning'];

  const message = 'Outreach was sent';

  const actionLabel1 = 'Try Again';
  const actionLabel2 = '';

  const props = {
    actions: [],
  };

  if (actionLabel1) {
    props.actions.push({
      label: actionLabel1,
      onClick: () => action('action button click: 1')(),
    });
  }
  if (actionLabel2) {
    props.actions.push({
      label: actionLabel2,
      onClick: () => action('action button click: 2')(),
    });
  }

  return (
    <div className="d-flex">
      {appearances.map((appearance, ind) => {
        return (
          <div key={ind} className="mr-5 mb-8">
            <Toast
              appearance={appearance}
              title={appearance.charAt(0).toUpperCase() + appearance.slice(1)}
              message={message}
              onClose={action('on-close clicked')}
              {...props}
            />
          </div>
        );
      })}
    </div>
  );
}"},"__isArgsStory":false,"__id":"components-toast-variants-toast-with-action--toast-with-action","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{"title":{"name":"title","description":"Title of `Toast`","type":{"required":true,"name":"string"},"table":{"type":{"summary":"string"},"defaultValue":null}},"appearance":{"name":"appearance","description":"Color of the `Toast`

