  return (
    <div>
      <Heading size="xxl">Design Tokens</Heading>
      <br />
      <br />
      <Heading size="m">Colors</Heading>
      <br />
      {tokenColors.map((data, idx) => {
        const heading =
          idx !== 4 && idx !== 9
