            : idx === 4
            ? 'Neutral'
            : 'Others';
        return (
          <div className="mt-5 mb-5" key={idx}>
            <Heading size="s">{heading}</Heading>
            <br />
            <Card className="h-100 overflow-hidden">
              <Table data={data} schema={colorSchema} />
            </Card>
            <br />
          </div>
        );
      })}
    </div>
  );
}"},"__isArgsStory":false,"__id":"others-design-tokens-colors--colors","globals":{"measureEnabled":false,"outline":false},"args":{},"argTypes":{}},"initialArgs":{},"argTypes":{}}

