{"args":{},"componentId":"patterns-forms-verification-code-input","title":"Patterns/Forms/Verification Code Input","kind":"Patterns/Forms/Verification Code Input","id":"patterns-forms-verification-code-input--verification-code-input","name":"Verification Code Input","story":"Verification Code Input","parameters":{"docs":{"inlineStories":true,"iframeHeight":100,"theme":{"base":"light","colorPrimary":"#0000001a","colorSecondary":"deepskyblue","appBg":"white","appContentBg":"white","appBorderColor":"#0000001a","appBorderRadius":4,"fontBase":""Nunito Sans", "Open Sans", sans-serif","fontCode":"monospace","textColor":"black","textInverseColor":"rgba(255,255,255,0.9)","textMutedColor":"#666666","barTextColor":"silver","barSelectedColor":"black","barBg":"white","inputBg":"white","inputBorder":"silver","inputTextColor":"black","inputBorderRadius":4,"brandTitle":"Masala Design System v2.10.0-0","brandUrl":"https://github.com/innovaccer/design-system/"},"docPage":{"customCode":"() => {
  class VerificationCodeInputCard extends React.Component {
    constructor(props) {
      super(props);

      this.correctValue = '555123';
      this.state = {
        isTimerStarted: false,
        timer: 30,
        loading: false,
        value: '',
        error: false,
      };

      this.onToogleLink = this.onToogleLink.bind(this);
      this.onCompleteHandler = this.onCompleteHandler.bind(this);
    }

    componentDidUpdate(prevProps, prevState) {
      const { timer, isTimerStarted } = this.state;

      if (isTimerStarted
        && (timer !== prevState.time || prevState.isTimerStarted !== isTimerStarted)
      ) {
        if (timer > 0) {
          setTimeout(() => {
            this.setState({
              timer: timer - 1,
            })
          }, 1000);
        }

        if (timer === 0) {
          this.setState({
            isTimerStarted: !isTimerStarted,
          });
        }
      }
    }

    onToogleLink() {
      if (this.state.loading || !!this.state.value) return;
      this.setState({
        isTimerStarted: true,
        timer: 30
      });
    };

    onCompleteHandler(value) {
      this.setState({
        loading: true,
        timer: 0,
        isTimerStarted: false,
      });

      setTimeout(() => {
        this.setState({
          value: value === this.correctValue ? value : '',
          loading: false,
          error: value !== this.correctValue
        });
      }, 2000);
    };

    render() {
      const { isTimerStarted, timer, loading, value, error } = this.state;
      const time = timer < 10 ? `0${timer}` : timer;

      return (
        <div>
          <div className="mb-5">
            <Text weight="strong">Note: </Text>
            <Text weight="medium">{`Verified value of Verification Code Input is ${this.correctValue} in this example.`}</Text>
          </div>
          <div className="w-50">
            {(value || error) && (
              <Message
                appearance={error ? 'alert' : 'success'}
                description={error? 'The code that you have entered is invalid or incorrect. Try again.' : 'Verification Successful.'}
                className="mb-5"
              />
            )}
            <Card className="py-6 px-6">
              <div className="d-flex flex-column">
                <Text weight="strong" size="large">Enter Verification Code</Text>
                <Text className="mt-3" appearance="subtle">
                  We have sent a 6 digit verification code to your phone (555) 555-1234
                </Text>
              </div>
              <Label withInput={true} className="mt-7">Verification code</Label>
              <div className="d-flex align-items-center">
                <VerificationCodeInput
                  fields={6}
                  onComplete={this.onCompleteHandler}
                  disabled={loading || !!value}
                />
                {loading && <Spinner className="ml-5" size="medium" />}
              </div>
              {isTimerStarted ? (
                <Text className="mt-7 d-flex" weight="medium">
                  {`Haven't recieved the code? Resend code in 0:${time}`}
                </Text>
              ) : (
                  <Text
                    className="mt-7 d-flex cursor-pointer"
                    appearance={loading || !!value ? 'disabled' : 'link'}
                    weight="medium"
                    onClick={this.onToogleLink}
                  >
                    Resend Code
                  </Text>
                )}
            </Card>
          </div>
        </div>
      );
    }
  };

  return <><VerificationCodeInputCard /></>
}","title":"Verification Code Input"}},"framework":"react","backgrounds":{"grid":{"cellSize":20,"opacity":0.5,"cellAmount":5},"values":[{"name":"light","value":"#F8F8F8"},{"name":"dark","value":"#333333"}]},"viewMode":"docs","actions":{"argTypesRegex":"^on[A-Z].*"},"a11y":{"element":"#root","manual":false},"viewport":{"viewports":{"iphone5":{"name":"iPhone 5","styles":{"height":"568px","width":"320px"},"type":"mobile"},"iphone6":{"name":"iPhone 6","styles":{"height":"667px","width":"375px"},"type":"mobile"},"iphone6p":{"name":"iPhone 6 Plus","styles":{"height":"736px","width":"414px"},"type":"mobile"},"iphone8p":{"name":"iPhone 8 Plus","styles":{"height":"736px","width":"414px"},"type":"mobile"},"iphonex":{"name":"iPhone X","styles":{"height":"812px","width":"375px"},"type":"mobile"},"iphonexr":{"name":"iPhone XR","styles":{"height":"896px","width":"414px"},"type":"mobile"},"iphonexsmax":{"name":"iPhone XS Max","styles":{"height":"896px","width":"414px"},"type":"mobile"},"iphonese2":{"name":"iPhone SE (2nd generation)","styles":{"height":"667px","width":"375px"},"type":"mobile"},"iphone12mini":{"name":"iPhone 12 mini","styles":{"height":"812px","width":"375px"},"type":"mobile"},"iphone12":{"name":"iPhone 12","styles":{"height":"844px","width":"390px"},"type":"mobile"},"iphone12promax":{"name":"iPhone 12 Pro Max","styles":{"height":"926px","width":"428px"},"type":"mobile"},"ipad":{"name":"iPad","styles":{"height":"1024px","width":"768px"},"type":"tablet"},"ipad10p":{"name":"iPad Pro 10.5-in","styles":{"height":"1112px","width":"834px"},"type":"tablet"},"ipad12p":{"name":"iPad Pro 12.9-in","styles":{"height":"1366px","width":"1024px"},"type":"tablet"},"galaxys5":{"name":"Galaxy S5","styles":{"height":"640px","width":"360px"},"type":"mobile"},"galaxys9":{"name":"Galaxy S9","styles":{"height":"740px","width":"360px"},"type":"mobile"},"nexus5x":{"name":"Nexus 5X","styles":{"height":"660px","width":"412px"},"type":"mobile"},"nexus6p":{"name":"Nexus 6P","styles":{"height":